WITH matched AS (SELECT e.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM promotions e LEFT JOIN promotions pr ON e.channel = pr.channel AND e.starts_on >= pr.starts_on AND e.starts_on < pr.ends_on + INTERVAL 30 DAYS) SELECT DATE_TRUNC('MONTH', starts_on) AS activity_month, CASE WHEN promo_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS promo_id_tier, CASE WHEN promotion_discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END AS promotion_discount_pct_tier, AVG(discount_pct) FILTER (WHERE channel = 'mobile') AS mobile_avg_discount_pct, COUNT(CASE WHEN channel = 'store' THEN 1 END) AS store_count FROM matched GROUP BY DATE_TRUNC('MONTH', starts_on), CASE WHEN promo_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN promotion_discount_pct >= 0.3 THEN 'HIGH' ELSE 'LOW' END;
